query:
SELECT id, name, cas_number, pubchem_cid, formula, molecular_weight, notes, olfactive_family, chemical_family 
FROM molecules 
WHERE name IN ('Zizanol', 'α-Vétivène', 'β-Vétispirène') OR cas_number IN ('41060-17-1', '5765-27-5', '27840-40-0');

